begin;
create function public.kalling_execution_comparable(p_transaction uuid,p_revision integer,p_action text,p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
 declare t kalling_private.execution_transactions;r text;d jsonb;c jsonb;n jsonb;begin
 select * into t from kalling_private.execution_transactions where id=p_transaction for update;r=kalling_private.execution_role(t.id);
 if r is distinct from 'advisor' or coalesce(kalling_private.role_for(t.firm_id),'') not in ('owner','admin') or t.state<>'Closed' or jsonb_array_length(t.data->'closes')=0 then raise exception 'A firm owner or administrator must review a documented completed acquisition.' using errcode='42501';end if;if t.revision<>p_revision then raise exception 'This transaction changed. Reload before saving.';end if;d=t.data;c=d->'comparables'->-1;
 if p_action='comp_withdraw' then
 if c is null or not kalling_private.execution_safe(p->>'note',20,2000) then raise exception 'Record why the authority or evidence is withdrawn.';end if;n=c||jsonb_build_object('disputed',true,'version',(c->>'version')::integer+1,'note',p->>'note','reviewer',kalling_private.actor_name(),'at',now());
 elsif p_action='comp_review' then
 if coalesce(p->>'state','') not in ('NJ','NY') or coalesce(p->>'basis','') not in ('Cash','Accrual') or coalesce(p->>'metric','') not in ('SDE','EBITDA') or not kalling_private.execution_safe(p->>'businessType',3,100) or not kalling_private.execution_safe(p->>'note',20,2000) or p->>'period'!~'^\d{4}-\d{2}-\d{2} to \d{4}-\d{2}-\d{2}$' or not coalesce(to_char(split_part(p->>'period',' to ',1)::date,'YYYY-MM-DD')=split_part(p->>'period',' to ',1) and to_char(split_part(p->>'period',' to ',2)::date,'YYYY-MM-DD')=split_part(p->>'period',' to ',2) and split_part(p->>'period',' to ',1)::date<=split_part(p->>'period',' to ',2)::date,false) then raise exception 'Record the deidentified transaction type, exact financial period, metric and accounting basis.';end if;
 if jsonb_typeof(p->'earnings') is distinct from 'number' or p->>'earnings'!~'^[0-9]+$' or (p->>'earnings')::numeric<=0 or (p->>'earnings')::numeric>100000000000000 or jsonb_typeof(p->'revenue') is distinct from 'number' or p->>'revenue'!~'^[0-9]+$' or (p->>'revenue')::numeric<=0 or (p->>'revenue')::numeric>100000000000000 or coalesce((p->>'recastVersion')::integer,0)<=0 or not kalling_private.execution_sources(t.id,p->'sources') or not kalling_private.execution_safe(p#>>'{authority,note}',30,2000) or not kalling_private.execution_safe(p#>>'{authority,professional}',3,160) or coalesce(p#>>'{authority,scope}','')<>'Internal deidentified analysis' or jsonb_typeof(p->'disputed') is distinct from 'boolean' then raise exception 'Review exact reconciled US cents, source versions and separate internal data-use authority.';end if;
 n=jsonb_build_object('version',coalesce((c->>'version')::integer,0)+1,'closeVersion',d->'closes'->-1->'version','state',p->>'state','businessType',p->>'businessType','period',p->>'period','basis',p->>'basis','metric',p->>'metric','earnings',p->'earnings','revenue',p->'revenue','recastVersion',p->'recastVersion','sources',p->'sources','authority',jsonb_build_object('note',p#>>'{authority,note}','professional',p#>>'{authority,professional}','scope','Internal deidentified analysis','at',now()),'reviewer',kalling_private.actor_name(),'at',now(),'disputed',p->'disputed','note',p->>'note');
 else raise exception 'Unknown comparable action';end if;
 perform kalling_private.execution_save(t,jsonb_set(d,'{comparables}',d->'comparables'||jsonb_build_array(n)),p_action,'Original valuation and closing history retained.');return kalling_private.execution_projection(t.id);end $$;
create function kalling_private.execution_comp_exclusions(t kalling_private.execution_transactions) returns text[] language plpgsql stable security definer set search_path='' as $$
 declare c jsonb=t.data->'comparables'->-1;closing jsonb=t.data->'closes'->-1;out text[]='{}';begin
 if t.state<>'Closed' or closing is null then out=array_append(out,'No documented close');end if;
 if coalesce((t.data->>'fictional')::boolean,true) or exists(select 1 from public.kalling_listings l where l.id=t.listing_id and l.sample) then out=array_append(out,'Fictional fixture');end if;
 if c is null then out=array_append(out,'No reviewed comparable');else
 if coalesce((c->>'disputed')::boolean,true) then out=array_append(out,'Disputed or authority withdrawn');end if;
 if c->>'closeVersion' is distinct from closing->>'version' then out=array_append(out,'Closing correction needs review');end if;
 if not kalling_private.execution_sources(t.id,c->'sources') or not kalling_private.execution_sources(t.id,closing->'evidence') then out=array_append(out,'Evidence changed');end if;
 if not kalling_private.execution_safe(c#>>'{authority,note}',30,2000) or c#>>'{authority,scope}' is distinct from 'Internal deidentified analysis' then out=array_append(out,'Internal data-use authority missing');end if;end if;return out;end $$;
create function public.kalling_execution_calibration() returns jsonb language plpgsql stable security definer set search_path='' as $$
 declare rows jsonb;groups jsonb;excluded jsonb;begin
 if kalling_private.advisor_role() is null then raise exception 'Internal analysis access denied' using errcode='42501';end if;
 select coalesce(jsonb_agg(jsonb_build_object('originId',t.id,'version',c->'version','closeVersion',closing->'version','businessType',c->>'businessType','state',c->>'state','date',closing->>'date','accountingBasis',c->>'basis','period',c->>'period','metric',c->>'metric','priceBasis',closing#>>'{amounts,basis}','fixedCents',closing#>'{amounts,fixed}','earningsCents',c->'earnings','revenueCents',c->'revenue','maximumContingentCents',closing#>'{amounts,earnoutMax}','realizedContingentCents',closing#>'{amounts,earnoutRealized}','multiple',(closing#>>'{amounts,fixed}')::numeric/(c->>'earnings')::numeric,'sources',(select jsonb_agg(jsonb_build_object('fileId',s->>'fileId','page',s->'page')) from jsonb_array_elements(c->'sources') s),'originalEstimate',t.data->'originalEstimate') order by t.id),'[]') into rows from kalling_private.execution_transactions t cross join lateral(select t.data->'comparables'->-1 c,t.data->'closes'->-1 closing) x where t.firm_id=kalling_private.house() and cardinality(kalling_private.execution_comp_exclusions(t))=0;
 select coalesce(jsonb_agg(g),'[]') into groups from(select (r->>'priceBasis')||' | '||(r->>'metric')||' | '||(r->>'accountingBasis') key,count(*) count,min(r->>'date') "from",max(r->>'date') "to",percentile_cont(0.5) within group(order by (r->>'multiple')::numeric) median,min((r->>'multiple')::numeric) min,max((r->>'multiple')::numeric) max,false "sufficientForRelease" from jsonb_array_elements(rows) r group by r->>'priceBasis',r->>'metric',r->>'accountingBasis') g;
 select coalesce(jsonb_agg(jsonb_build_object('originId',t.id,'reasons',to_jsonb(kalling_private.execution_comp_exclusions(t)))),'[]') into excluded from kalling_private.execution_transactions t where t.firm_id=kalling_private.house() and cardinality(kalling_private.execution_comp_exclusions(t))>0;
 return jsonb_build_object('datasetVersion','kalling-comps-v1:'||md5(rows::text),'rows',rows,'groups',groups,'excluded',excluded,'productionModelChanged',false,'limitations',jsonb_build_array('Internal completed-sale sample; selection bias and small populations can distort results.','Fixed consideration divided by exact supported SDE or EBITDA. Maximum earnout is separate.','Accounting and price bases are separate. Review unusual observations before any experiment.','Production valuation coefficients are unchanged. Experimental releases need separate review and held-out evaluation.'));end $$;
revoke all on function kalling_private.execution_comp_exclusions(kalling_private.execution_transactions) from public,anon,authenticated;
revoke all on function public.kalling_execution_comparable(uuid,integer,text,jsonb),public.kalling_execution_calibration() from public,anon;grant execute on function public.kalling_execution_comparable(uuid,integer,text,jsonb),public.kalling_execution_calibration() to authenticated;
commit;

